const http = require('http');
const { EventEmitter } = require('events');

class PDFStyleParser extends EventEmitter {
  constructor(options = {}) {
    super();
    this.maxNesting = options.maxNesting || 10;
    this.cache = new Map();
    this.compiledPatterns = this._buildPatterns();
  }

  _buildPatterns() {
    return {
      colorHex: /^#([0-9a-fA-F]{3}|[0-9a-fA-F]{6})$/,
      colorRgb: /^rgb\(\s*\d{1,3}\s*,\s*\d{1,3}\s*,\s*\d{1,3}\s*\)$/,
      fontSize: /^\d+(\.\d+)?(px|pt|em|rem)$/,
      fontWeight: /^(normal|bold|lighter|bolder|[1-9]00)$/,
      margin: /^(\d+(\.\d+)?(px|pt|em|rem)\s*){1,4}$/,
      selector: this._buildSelectorPattern()
    };
  }

  _buildSelectorPattern() {
    // Matches CSS-like selectors for PDF element targeting
    // Supports: .class, #id, element, element.class, nested > selectors
    const ident = '[a-zA-Z_][a-zA-Z0-9_-]*';
    const classOrId = `(?:[.#]${ident})`;
    const attrMatch = `(?:\\[${ident}(?:[~|^$*]?=(?:"[^"]*"|'[^']*'|${ident}))?\\])`;
    const pseudo = `(?:::?${ident}(?:\\([^)]*\\))?)`;
    const simple = `(?:${ident}|${classOrId})(?:${classOrId}|${attrMatch}|${pseudo})*`;
    const combinator = `\\s*[>+~]?\\s*`;
    const full = `^${simple}(?:${combinator}${simple})*$`;
    return new RegExp(full);
  }

  parseStyleBlock(input) {
    if (typeof input !== 'string') {
      throw new TypeError('Style input must be a string');
    }
    if (input.length > 10000) {
      throw new RangeError('Style input exceeds maximum length');
    }

    const cacheKey = input.substring(0, 200);
    if (this.cache.has(cacheKey)) {
      return this.cache.get(cacheKey);
    }

    const rules = this._extractRules(input);
    const parsed = rules.map(rule => this._parseRule(rule));

    this.cache.set(cacheKey, parsed);
    if (this.cache.size > 1000) {
      const firstKey = this.cache.keys().next().value;
      this.cache.delete(firstKey);
    }

    return parsed;
  }

  _extractRules(input) {
    const rules = [];
    let depth = 0;
    let current = '';

    for (let i = 0; i < input.length; i++) {
      const ch = input[i];
      if (ch === '{') depth++;
      else if (ch === '}') {
        depth--;
        if (depth === 0) {
          rules.push(current + '}');
          current = '';
          continue;
        }
      }
      current += ch;
    }
    return rules;
  }

  _parseRule(rule) {
    const braceIdx = rule.indexOf('{');
    if (braceIdx === -1) return null;

    const selector = rule.substring(0, braceIdx).trim();
    const body = rule.substring(braceIdx + 1, rule.length - 1).trim();

    const validSelector = this._validateSelector(selector);
    const properties = this._parseProperties(body);

    return { selector: validSelector, properties };
  }

  _validateSelector(selector) {
    if (this.compiledPatterns.selector.test(selector)) {
      return selector;
    }
    this.emit('warning', `Invalid selector: ${selector.substring(0, 50)}`);
    return null;
  }

  _parseProperties(body) {
    const props = {};
    const declarations = body.split(';').filter(d => d.trim());

    for (const decl of declarations) {
      const colonIdx = decl.indexOf(':');
      if (colonIdx === -1) continue;

      const prop = decl.substring(0, colonIdx).trim();
      const value = decl.substring(colonIdx + 1).trim();

      if (this._validateProperty(prop, value)) {
        props[prop] = value;
      }
    }
    return props;
  }

  _validateProperty(prop, value) {
    const validators = {
      'color': v => this.compiledPatterns.colorHex.test(v) || this.compiledPatterns.colorRgb.test(v),
      'background-color': v => this.compiledPatterns.colorHex.test(v) || this.compiledPatterns.colorRgb.test(v),
      'font-size': v => this.compiledPatterns.fontSize.test(v),
      'font-weight': v => this.compiledPatterns.fontWeight.test(v),
      'margin': v => this.compiledPatterns.margin.test(v),
      'padding': v => this.compiledPatterns.margin.test(v)
    };

    if (validators[prop]) {
      return validators[prop](value);
    }
    return /^[a-zA-Z0-9_.\-\s#(),/%]+$/.test(value);
  }
}

class PDFGenerator {
  constructor(config = {}) {
    this.styleParser = new PDFStyleParser(config.parserOptions);
    this.server = null;
    this.connections = new Set();
    this.isShuttingDown = false;
  }

  start(port = 3000) {
    this.server = http.createServer((req, res) => this._handleRequest(req, res));

    this.server.on('connection', (conn) => {
      this.connections.add(conn);
      conn.on('close', () => this.connections.delete(conn));
    });

    this.server.listen(port, () => {
      console.log(`PDF Generator listening on port ${port}`);
    });

    this._setupGracefulShutdown();
    return this.server;
  }

  _setupGracefulShutdown() {
    const shutdown = (signal) => {
      if (this.isShuttingDown) return;
      this.isShuttingDown = true;
      console.log(`\nReceived ${signal}. Graceful shutdown...`);

      this.server.close(() => {
        console.log('Server closed.');
        process.exit(0);
      });

      setTimeout(() => {
        console.error('Forced shutdown after timeout');
        this.connections.forEach(conn => conn.destroy());
        process.exit(1);
      }, 30000);
    };

    process.on('SIGTERM', () => shutdown('SIGTERM'));
    process.on('SIGINT', () => shutdown('SIGINT'));
  }

  async _handleRequest(req, res) {
    if (this.isShuttingDown) {
      res.writeHead(503, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: 'Server shutting down' }));
      return;
    }

    if (req.method === 'POST' && req.url === '/api/generate') {
      try {
        const body = await this._readBody(req);
        const data = JSON.parse(body);

        if (!data.styles || !data.content) {
          res.writeHead(400, { 'Content-Type': 'application/json' });
          res.end(JSON.stringify({ error: 'Missing styles or content' }));
          return;
        }

        const parsedStyles = this.styleParser.parseStyleBlock(data.styles);
        const pdfBuffer = this._renderPDF(data.content, parsedStyles);

        res.writeHead(200, { 'Content-Type': 'application/pdf' });
        res.end(pdfBuffer);
      } catch (err) {
        res.writeHead(500, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ error: err.message }));
      }
    } else {
      res.writeHead(404);
      res.end();
    }
  }

  _readBody(req) {
    return new Promise((resolve, reject) => {
      const chunks = [];
      let size = 0;
      req.on('data', chunk => {
        size += chunk.length;
        if (size > 1048576) {
          req.destroy();
          reject(new Error('Body too large'));
          return;
        }
        chunks.push(chunk);
      });
      req.on('end', () => resolve(Buffer.concat(chunks).toString()));
      req.on('error', reject);
    });
  }

  _renderPDF(content, styles) {
    // Simplified PDF rendering stub
    const header = '%PDF-1.4\n';
    const body = `1 0 obj\n<< /Type /Catalog >>\nendobj\n`;
    return Buffer.from(header + body);
  }
}

module.exports = { PDFGenerator, PDFStyleParser };

if (require.main === module) {
  const generator = new PDFGenerator();
  generator.start(process.env.PORT || 3000);
}
